import{_ as l,a0 as a,w as r,s as i,I as n,x as e,a1 as p,A as s,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"探秘“棧”之旅 | LCTT x X-CMD","titleTemplate":false,"description":"探秘“棧”之旅 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"探秘“棧”之旅 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"探秘“棧”之旅 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20140510 Journey to the Stack Part I","title":"探秘“棧”之旅","tag":"201805","desc":""},"relativePath":"201805/20140510 Journey to the Stack Part I.md","filePath":"[post].md"}'),m={name:"201805/20140510 Journey to the Stack Part I.md"};function u(b,t,f,g,T,C){const o=a("Link");return r(),i("div",null,[t[39]||(t[39]=n("h1",{id:"探秘-棧-之旅",tabindex:"-1"},[e("探秘“棧”之旅 "),n("a",{class:"header-anchor",href:"#探秘-棧-之旅","aria-label":"Permalink to “探秘“棧”之旅”"},"​")],-1)),n("p",null,[t[1]||(t[1]=e("早些時候，我們探索了 ",-1)),p(o,{href:"https://linux.cn/article-9255-1.html"},{default:s(()=>[...t[0]||(t[0]=[e("“內存中的程序之秘”",-1)])]),_:1}),t[2]||(t[2]=e("，我們欣賞了在一台電腦中是如何運行我們的程序的。今天，我們去探索",-1)),t[3]||(t[3]=n("em",null,"棧的調用",-1)),t[4]||(t[4]=e("，它在大多數編程語言和虛擬機中都默默地存在。在此過程中，我們將接觸到一些平時很難見到的東西，像",-1)),t[5]||(t[5]=n("ruby",null,[e("閉包"),n("rt",null,"closure")],-1)),t[6]||(t[6]=e("、遞歸、以及緩衝溢出等等。但是，我們首先要作的事情是，描繪出棧是如何運作的。",-1))]),t[40]||(t[40]=d('<p>棧非常重要，因為它追蹤着一個程序中運行的<em>函數</em>，而函數又是一個軟件的重要組成部分。事實上，程序的內部操作都是非常簡單的。它大部分是由函數向棧中推入數據或者從棧中彈出數據的相互調用組成的，而在堆上為數據分配內存才能在跨函數的調用中保持數據。不論是低級的 C 軟件還是像 JavaScript 和 C# 這樣的基於虛擬機的語言，它們都是這樣的。而對這些行為的深刻理解，對排錯、性能調優以及大概瞭解究竟發生了什麼是非常重要的。</p><p>當一個函數被調用時，將會創建一個<ruby>棧幀<rt>stack frame</rt></ruby>去支持函數的運行。這個棧幀包含函數的<em>局部變量</em>和調用者傳遞給它的<em>參數</em>。這個棧幀也包含了允許被調用的函數（<em>callee</em>）安全返回給其調用者的內部事務信息。棧幀的精確內容和結構因處理器架構和函數調用規則而不同。在本文中我們以 Intel x86 架構和使用 C 風格的函數調用（<code>cdecl</code>）的棧為例。下圖是一個處於棧頂部的一個單個棧幀：</p><p><img src="https://manybutfinite.com/img/stack/stackIntro.png" alt=""></p><p>在圖上的場景中，有三個 CPU 寄存器進入棧。<ruby>棧指針<rt>stack pointer</rt></ruby> <code>esp</code>（LCTT 譯註：擴展棧指針寄存器） 指向到棧的頂部。棧的頂部總是被最<em>後一個推入到棧且還沒有彈出</em>的東西所佔據，就像現實世界中堆在一起的一疊盤子或者 100 美元大鈔一樣。</p><p>保存在 <code>esp</code> 中的地址始終在變化着，因為棧中的東西不停被推入和彈出，而它總是指向棧中的最後一個推入的東西。許多 CPU 指令的一個副作用就是自動更新 <code>esp</code>，離開寄存器而使用棧是行不通的。</p><p>在 Intel 的架構中，絕大多數情況下，棧的增長是向着<em>低位內存地址</em>的方向。因此，這個“頂部” 在包含數據的棧中是處於低位的內存地址（在這種情況下，包含的數據是 <code>local_buffer</code>）。注意，關於從 <code>esp</code> 到 <code>local_buffer</code> 的箭頭不是隨意連接的。這個箭頭代表着事務：它<em>專門</em>指向到由 <code>local_buffer</code> 所擁有的<em>第一個字節</em>，因為，那是一個保存在 <code>esp</code> 中的精確地址。</p><p>第二個寄存器跟蹤的棧是 <code>ebp</code>（LCTT 譯註：擴展基址指針寄存器），它包含一個<ruby>基指針<rt>base pointer</rt></ruby>或者稱為<ruby>幀指針<rt>frame pointer</rt></ruby>。它指向到一個<em>當前運行</em>的函數的棧幀內的固定位置，並且它為參數和局部變量的訪問提供一個穩定的參考點（基址）。僅當開始或者結束調用一個函數時，<code>ebp</code> 的內容才會發生變化。因此，我們可以很容易地處理在棧中的從 <code>ebp</code> 開始偏移後的每個東西。如圖所示。</p>',7)),n("p",null,[t[8]||(t[8]=e("不像 ",-1)),t[9]||(t[9]=n("code",null,"esp",-1)),t[10]||(t[10]=e("， ",-1)),t[11]||(t[11]=n("code",null,"ebp",-1)),t[12]||(t[12]=e(" 大多數情況下是在程序代碼中通過花費很少的 CPU 來進行維護的。有時候，完成拋棄 ",-1)),t[13]||(t[13]=n("code",null,"ebp",-1)),t[14]||(t[14]=e(" 有一些性能優勢，可以通過 ",-1)),p(o,{href:"http://stackoverflow.com/questions/14666665/trying-to-understand-gcc-option-fomit-frame-pointer"},{default:s(()=>[...t[7]||(t[7]=[e("編譯標誌",-1)])]),_:1}),t[15]||(t[15]=e(" 來做到這一點。Linux 內核就是一個這樣做的示例。",-1))]),t[41]||(t[41]=d(`<p>最後，<code>eax</code>（LCTT 譯註：擴展的 32 位通用數據寄存器）寄存器慣例被用來轉換大多數 C 數據類型返回值給調用者。</p><p>現在，我們來看一下在我們的棧幀中的數據。下圖清晰地按字節展示了字節的內容，就像你在一個調試器中所看到的內容一樣，內存是從左到右、從頂部至底部增長的，如下圖所示：</p><p><img src="https://manybutfinite.com/img/stack/frameContents.png" alt=""></p><p>局部變量 <code>local_buffer</code> 是一個字節數組，包含一個由 null 終止的 ASCII 字符串，這是 C 程序中的一個基本元素。這個字符串可以讀取自任意地方，例如，從鍵盤輸入或者來自一個文件，它只有 7 個字節的長度。因為，<code>local_buffer</code> 只能保存 8 字節，所以還剩下 1 個未使用的字節。<em>這個字節的內容是未知的</em>，因為棧不斷地推入和彈出，<em>除了你寫入的之外</em>，你根本不會知道內存中保存了什麼。這是因為 C 編譯器並不為棧幀初始化內存，所以它的內容是未知的並且是隨機的 —— 除非是你自己寫入。這使得一些人對此很困惑。</p><p>再往上走，<code>local1</code> 是一個 4 字節的整數，並且你可以看到每個字節的內容。它似乎是一個很大的數字，在8 後面跟着的都是零，在這裏可能會誤導你。</p><p>Intel 處理器是<ruby>小端<rt>little endian</rt></ruby>機器，這表示在內存中的數字也是首先從小的一端開始的。因此，在一個多字節數字中，較小的部分在內存中處於最低端的地址。因為一般情況下是從左邊開始顯示的，這背離了我們通常的數字表示方式。我們討論的這種從小到大的機制，使我想起《格里佛遊記》：就像小人國的人們吃雞蛋是從小頭開始的一樣，Intel 處理器處理它們的數字也是從字節的小端開始的。</p><p>因此，<code>local1</code> 事實上只保存了一個數字 8，和章魚的腿數量一樣。然而，<code>param1</code> 在第二個字節的位置有一個值 2，因此，它的數學上的值是 <code>2 * 256 = 512</code>（我們與 256 相乘是因為，每個位置值的範圍都是從 0 到 255）。同時，<code>param2</code> 承載的數量是 <code>1 * 256 * 256 = 65536</code>。</p><p>這個棧幀的內部數據是由兩個重要的部分組成：<em>前一個</em>棧幀的地址（保存的 <code>ebp</code> 值）和函數退出才會運行的指令的地址（返回地址）。它們一起確保了函數能夠正常返回，從而使程序可以繼續正常運行。</p><p>現在，我們來看一下棧幀是如何產生的，以及去建立一個它們如何共同工作的內部藍圖。首先，棧的增長是非常令人困惑的，因為它與你你預期的方式相反。例如，在棧上分配一個 8 字節，就要從 <code>esp</code> 減去 8，去，而減法是與增長不同的奇怪方式。</p><p>我們來看一個簡單的 C 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Simple Add Program - add.c</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int add(int a, int b)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>	int result = a + b;</span></span>
<span class="line"><span>	return result;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main(int argc)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>	int answer;</span></span>
<span class="line"><span>	answer = add(40, 2);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><em>簡單的加法程序 - add.c</em></p>`,12)),n("p",null,[t[18]||(t[18]=e("假設我們在 Linux 中不使用命令列參數去運行它。當你運行一個 C 程序時，實際運行的第一行代碼是在 C 運行時庫裏，由它來調用我們的 ",-1)),t[19]||(t[19]=n("code",null,"main",-1)),t[20]||(t[20]=e(" 函數。下圖展示了程序運行時每一步都發生了什麼。每個圖鏈接的 GDB 輸出展示了內存和寄存器的狀態。你也可以看到所使用的 ",-1)),p(o,{href:"https://github.com/gduarte/blog/blob/master/code/x86-stack/add-gdb-commands.txt"},{default:s(()=>[...t[16]||(t[16]=[e("GDB 命令",-1)])]),_:1}),t[21]||(t[21]=e("，以及整個 ",-1)),p(o,{href:"https://github.com/gduarte/blog/blob/master/code/x86-stack/add-gdb-output.txt"},{default:s(()=>[...t[17]||(t[17]=[e("GDB 輸出",-1)])]),_:1}),t[22]||(t[22]=e("。如下：",-1))]),t[42]||(t[42]=d('<p><img src="https://manybutfinite.com/img/stack/mainProlog.png" alt=""></p><p>第 2 步和第 3 步，以及下面的第 4 步，都只是函數的<ruby>序言<rt>prologue</rt></ruby>，幾乎所有的函數都是這樣的：<code>ebp</code> 的當前值被保存到了棧的頂部，然後，將 <code>esp</code> 的內容拷貝到 <code>ebp</code>，以建立一個新的棧幀。<code>main</code> 的序言和其它函數一樣，但是，不同之處在於，當程序啓動時 <code>ebp</code> 被清零。</p><p>如果你去檢查棧下方（右邊）的整形變量（<code>argc</code>），你將找到更多的數據，包括指向到程序名和命令列參數（傳統的 C 的 <code>argv</code>）、以及指向 Unix 環境變量以及它們真實的內容的指針。但是，在這裏這些並不是重點，因此，繼續向前調用 <code>add()</code>：</p><p><img src="https://manybutfinite.com/img/stack/callAdd.png" alt=""></p><p>在 <code>main</code> 從 <code>esp</code> 減去 12 之後得到它所需的棧空間，它為 <code>a</code> 和 <code>b</code> 設置值。在內存中的值展示為十六進制，並且是小端格式，與你從調試器中看到的一樣。一旦設置了參數值，<code>main</code> 將調用 <code>add</code>，並且開始運行：</p><p><img src="https://manybutfinite.com/img/stack/addProlog.png" alt=""></p><p>現在，有一點小激動！我們進入了另一個函數序言，但這次你可以明確看到棧幀是如何從 <code>ebp</code> 到棧建立一個鏈表。這就是調試器和高級語言中的 <code>Exception</code> 對象如何對它們的棧進行跟蹤的。當一個新幀產生時，你也可以看到更多這種典型的從 <code>ebp</code> 到 <code>esp</code> 的捕獲。我們再次從 <code>esp</code> 中做減法得到更多的棧空間。</p><p>當 <code>ebp</code> 寄存器的值拷貝到內存時，這裏也有一個稍微有些怪異的字節逆轉。在這裏發生的奇怪事情是，寄存器其實並沒有字節順序：因為對於內存，沒有像寄存器那樣的“增長的地址”。因此，慣例上調試器以對人類來説最自然的格式展示了寄存器的值：數位從最重要的到最不重要。因此，這個在小端機器中的副本的結果，與內存中常用的從左到右的標記法正好相反。我想用圖去展示你將會看到的東西，因此有了下面的圖。</p><p>在比較難懂的部分，我們增加了註釋：</p><p><img src="https://manybutfinite.com/img/stack/doAdd.png" alt=""></p><p>這是一個臨時寄存器，用於幫你做加法，因此沒有什麼警報或者驚喜。對於加法這樣的作業，棧的動作正好相反，我們留到下次再講。</p>',11)),n("p",null,[t[24]||(t[24]=e("對於任何讀到這裏的人都應該有一個小禮物，因此，我做了一個大的圖表展示了 ",-1)),p(o,{href:"https://manybutfinite.com/img/stack/callSequence.png"},{default:s(()=>[...t[23]||(t[23]=[e("組合到一起的所有步驟",-1)])]),_:1}),t[25]||(t[25]=e("。",-1))]),t[43]||(t[43]=n("p",null,"一旦把它們全部佈置好了，看上起似乎很乏味。這些小方框給我們提供了很多幫助。事實上，在計算機科學中，這些小方框是主要的展示工具。我希望這些圖片和寄存器的移動能夠提供一種更直觀的構想圖，將棧的增長和內存的內容整合到一起。從軟件的底層運作來看，我們的軟件與一個簡單的圖靈機器差不多。",-1)),t[44]||(t[44]=n("p",null,"這就是我們棧探秘的第一部分，再講一些內容之後，我們將看到構建在這個基礎上的高級編程的概念。下週見！",-1)),t[45]||(t[45]=n("hr",null,null,-1)),n("p",null,[t[27]||(t[27]=e("via:",-1)),p(o,{href:"https://manybutfinite.com/post/journey-to-the-stack/"},{default:s(()=>[...t[26]||(t[26]=[e("https://manybutfinite.com/post/journey-to-the-stack/",-1)])]),_:1})]),n("p",null,[t[31]||(t[31]=e("作者：",-1)),p(o,{href:"http://duartes.org/gustavo/blog/about/"},{default:s(()=>[...t[28]||(t[28]=[e("Gustavo Duarte",-1)])]),_:1}),t[32]||(t[32]=e(" 譯者：",-1)),p(o,{href:"https://github.com/qhwdw"},{default:s(()=>[...t[29]||(t[29]=[e("qhwdw",-1)])]),_:1}),t[33]||(t[33]=e(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[30]||(t[30]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[36]||(t[36]=e("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[34]||(t[34]=[e("LCTT",-1)])]),_:1}),t[37]||(t[37]=e(" 原創編譯，",-1)),p(o,{href:"https://linux.cn/"},{default:s(()=>[...t[35]||(t[35]=[e("Linux中國",-1)])]),_:1}),t[38]||(t[38]=e(" 榮譽推出",-1))])])}const c=l(m,[["render",u]]);export{x as __pageData,c as default};
